fun main() {
    val a = intArrayOf(3, 1, 2)
    println(a.sum())
    println(a.max())
    println(a.map { it * 2 })
    println(a.toList())
    println(a.joinToString())
    println(a.any { it > 2 })
    println(a.count { it > 1 })
    println(a.reversed())
    println(a.average())
    println(a.filter { it > 1 })
    println(a.sortedDescending())
    println(a.copyOf().contentToString())
    println(a.copyOfRange(0, 2).toList())
    println(a.contentEquals(intArrayOf(3, 1, 2)))
    a.sort()
    println(a.contentToString())
    a.reverse()
    println(a.contentToString())
    a.fill(9)
    println(a.contentToString())
    println((intArrayOf(1, 2) + 3).contentToString())
    val d = IntArray(4)
    intArrayOf(1, 2).copyInto(d, 1)
    println(d.contentToString())
    val s = arrayOf("b", "c", "a")
    println(s.sorted())
    s.sort()
    println(s.contentToString())
    s.sortDescending()
    println(s.contentToString())
    println(s.copyOfRange(1, 3).contentToString())
    println(s.reversedArray().contentToString())
    println(s.map { it.uppercase() })
    println(s.indexOf("b"))
    println(listOf(1, 2).toTypedArray().contentToString())
    println(listOf(4, 5).toIntArray().contentToString())
    println(doubleArrayOf(1.0, 2.0, 4.0).average())
    println(charArrayOf('a', 'c', 'b').max())
    println(longArrayOf(5L, 3L).sorted())
    println(intArrayOf(5, 4, 3, 2, 1).also { it.sort(1, 4) }.contentToString())
}
